args.sparql:
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?paternalGrandfather ?paternalGrandfatherLabel WHERE {
  dbr:Christopher_of_Werle dbp:father ?father .
  ?father dbp:father ?paternalGrandfather .
  OPTIONAL {
    ?paternalGrandfather rdfs:label ?paternalGrandfatherLabel .
    FILTER (langMatches(lang(?paternalGrandfatherLabel), "EN"))
  }
}
LIMIT 20

